import{_ as a,o as t,c as s,ao as i}from"./chunks/framework.mkujAfhU.js";const k=JSON.parse('{"title":"Downloads, updates and cache","description":"","frontmatter":{},"headers":[],"relativePath":"30-manual/40-data-management.md","filePath":"30-manual/40-data-management.md","lastUpdated":null}'),l={name:"30-manual/40-data-management.md"};function n(h,e,d,r,o,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="updates" tabindex="-1">Downloads, updates and cache <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Downloads, updates and cache {#updates}&quot;">​</a></h1><p><a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.database"><code>database</code></a> hides all of this behind one call. This page explains what happens underneath, so you can control it and fix it when something goes wrong.</p><h2 id="Where-the-data-live" tabindex="-1">Where the data live <a class="header-anchor" href="#Where-the-data-live" aria-label="Permalink to &quot;Where the data live {#Where-the-data-live}&quot;">​</a></h2><p>Everything is stored under one root directory, returned by <a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.database_dir"><code>database_dir</code></a>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Platform</th><th style="text-align:left;">Default location</th></tr></thead><tbody><tr><td style="text-align:left;">Windows</td><td style="text-align:left;"><code>%LOCALAPPDATA%\\ThermophysicalDB</code></td></tr><tr><td style="text-align:left;">macOS</td><td style="text-align:left;"><code>~/Library/Application Support/ThermophysicalDB</code></td></tr><tr><td style="text-align:left;">Linux</td><td style="text-align:left;"><code>$XDG_DATA_HOME/ThermophysicalDB</code> (default <code>~/.local/share/ThermophysicalDB</code>)</td></tr></tbody></table><p>Inside it, each data source has its own folder. The NIST archive lives in <code>thermoml/</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ThermoML.vYYYY-MM-DD.tgz</code></td><td style="text-align:left;">the archive exactly as NIST publishes it</td></tr><tr><td style="text-align:left;"><code>manifest.toml</code></td><td style="text-align:left;">version, SHA-256 digest, source URL, download date and size of the archive. Written last: a manifest on disk always describes a complete, verified archive.</td></tr><tr><td style="text-align:left;"><code>dataset.jld2</code></td><td style="text-align:left;">the parsed database as flat arrays (the binary cache)</td></tr><tr><td style="text-align:left;"><code>dataset.toml</code></td><td style="text-align:left;">which archive and schema version the cache was built from. Written last, so a cache without it is ignored.</td></tr></tbody></table><p>To keep the data somewhere else (a larger disk, a shared folder), use either of these. The environment variable wins when both are set:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set_database_dir!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;D:/data/thermophysical&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># stored in the active environment&#39;s LocalPreferences.toml</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> THERMOPHYSICALDB_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/shared/thermophysical   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># applies to every environment</span></span></code></pre></div><p>Existing data are not moved. <a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.reset_database_dir!"><code>reset_database_dir!</code></a> removes the preference again.</p><h2 id="What-database-does" tabindex="-1">What <code>database()</code> does <a class="header-anchor" href="#What-database-does" aria-label="Permalink to &quot;What \`database()\` does {#What-database-does}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><ol><li><p>Returns the object already built in this session, if there is one.</p></li><li><p>Makes sure a verified archive is installed (<code>ensure_archive</code>): downloads it if missing, or checks whether NIST has a newer one.</p></li><li><p>Loads the binary cache if it matches the installed archive; otherwise parses the archive and writes the cache.</p></li></ol><p>The keywords change this behaviour:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Keyword</th><th style="text-align:left;">Effect</th></tr></thead><tbody><tr><td style="text-align:left;"><code>update = :notify</code> (default)</td><td style="text-align:left;">If NIST has a newer archive, keep the local one and log a warning.</td></tr><tr><td style="text-align:left;"><code>update = :install</code></td><td style="text-align:left;">Download and switch to the newer archive.</td></tr><tr><td style="text-align:left;"><code>update = :never</code></td><td style="text-align:left;">Do not contact NIST at all. Use this offline.</td></tr><tr><td style="text-align:left;"><code>reload = true</code></td><td style="text-align:left;">Repeat the update check and reload, even within the same session.</td></tr><tr><td style="text-align:left;"><code>rebuild = true</code></td><td style="text-align:left;">Also ignore the cache and parse the archive again.</td></tr><tr><td style="text-align:left;"><code>progress = false</code></td><td style="text-align:left;">No progress bars, useful in scripts and in CI.</td></tr></tbody></table><h2 id="Checking-and-updating-by-hand" tabindex="-1">Checking and updating by hand <a class="header-anchor" href="#Checking-and-updating-by-hand" aria-label="Permalink to &quot;Checking and updating by hand {#Checking-and-updating-by-hand}&quot;">​</a></h2><p><a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.check_update"><code>check_update</code></a> compares the local archive with the latest one published by NIST. It never throws because of network problems: if NIST cannot be reached it falls back to the releases the package knows, and says so in <code>source</code>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> check_update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">state       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># :not_installed, :up_to_date, :update_available or :unknown</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">latest      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the most recent release known</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># :remote if NIST answered, :builtin otherwise</span></span></code></pre></div><p><a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.update_database!"><code>update_database!</code></a> installs the latest archive only if the local one is missing or outdated. Old archives are deleted after a successful installation.</p><h2 id="Integrity" tabindex="-1">Integrity <a class="header-anchor" href="#Integrity" aria-label="Permalink to &quot;Integrity {#Integrity}&quot;">​</a></h2><p>Every installation follows the same safe sequence, whether the file was downloaded or supplied by you:</p><ol><li><p>the archive is written to a temporary <code>.part</code> file;</p></li><li><p>its SHA-256 digest is compared with the one NIST publishes (or with a digest that you provide);</p></li><li><p>only if they match is the file moved into place;</p></li><li><p>the manifest is written last.</p></li></ol><p>A download that was interrupted, truncated or corrupted never looks like a valid installation, and a digest mismatch installs nothing.</p><h2 id="When-the-download-fails" tabindex="-1">When the download fails <a class="header-anchor" href="#When-the-download-fails" aria-label="Permalink to &quot;When the download fails {#When-the-download-fails}&quot;">​</a></h2><p>The archive is served by NIST through a redirect, and some networks, proxies and firewalls refuse the connection. ThermophysicalDB.jl does not give up at the first error:</p><ul><li><p>A download makes up to <strong>four attempts</strong>, pausing 2, 5 and 10 seconds between them. Each pause is announced in a warning with the reason for the previous failure.</p></li><li><p>Within each attempt it tries up to <strong>three independent ways</strong> of fetching the file: Julia&#39;s own downloader, the same downloader with a browser-style <code>User-Agent</code>, and the <code>curl</code> program of the operating system (which uses the system&#39;s network stack, certificates and proxy settings) when it is available.</p></li><li><p>A partial file is never left behind.</p></li></ul><p>If every attempt fails, the error lists each try and what went wrong, and says what to do:</p><ol><li><p><strong>Check the connection, VPN or proxy.</strong> If your network requires a proxy, set the <code>HTTPS_PROXY</code> environment variable before starting Julia.</p></li><li><p><strong>Download the file in a browser</strong> from <a href="https://data.nist.gov/od/id/mds2-2422" target="_blank" rel="noreferrer">https://data.nist.gov/od/id/mds2-2422</a> and install it with <a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.install_archive!"><code>install_archive!</code></a>.</p></li><li><p><strong>Try again later.</strong> The NIST servers sometimes refuse requests temporarily.</p></li></ol><h2 id="Installing-an-archive-from-a-file" tabindex="-1">Installing an archive from a file <a class="header-anchor" href="#Installing-an-archive-from-a-file" aria-label="Permalink to &quot;Installing an archive from a file {#Installing-an-archive-from-a-file}&quot;">​</a></h2><p><a href="/ThermophysicalDB.jl/dev/95-reference#ThermophysicalDB.install_archive!"><code>install_archive!</code></a> installs a file that is already on your disk, exactly as a download would be installed: verified, copied into the data directory and recorded in the manifest.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">install_archive!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:/Users/me/Downloads/ThermoML.v2020-09-30.tgz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>The digest is taken from the <code>sha256</code> keyword, else from a <code>ThermoML.v2020-09-30.tgz.sha256</code> file next to the archive, else from the releases that the package knows about. The version is read from the file name when <code>version</code> is not given. A file whose digest does not match is rejected and nothing is installed.</p><h2 id="In-automated-builds" tabindex="-1">In automated builds <a class="header-anchor" href="#In-automated-builds" aria-label="Permalink to &quot;In automated builds {#In-automated-builds}&quot;">​</a></h2><p>Parsing the archive takes minutes, so a continuous-integration job should keep the data directory between runs. Point the package at a directory you can cache, and silence the progress bars:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> THERMOPHYSICALDB_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$RUNNER_TEMP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/thermophysicaldb&quot;</span></span></code></pre></div><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">db </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(progress </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The documentation of this package is built that way: the data directory is restored from the cache of the workflow, so only a change to the parser causes a new parse.</p>`,38)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
